        border-radius:5px;background:#f5f5f5;cursor:pointer;font-size:12px;">↻ Reload</button>
  </div>

  <script>
    // Show error overlay if module scripts fail or take too long
    let _rendered = false;
    const _errOverlay = document.getElementById('err-overlay');
    window.__markRendered = () => { _rendered = true; _errOverlay.style.display = 'none'; };
    window.addEventListener('error', (e) => {
      if (!_rendered) {
        document.getElementById('err-msg').textContent = '⚠ ' + (e.message || 'Figure failed to load');
        _errOverlay.style.display = 'flex';
      }
    });
    // Timeout fallback: if nothing renders in 12s, show overlay
    setTimeout(() => {
      if (!_rendered) { _errOverlay.style.display = 'flex'; }
    }, 12000);
  </script>

  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    /* ── Renderer ────────────────────────────────────────────────────────── */
    const canvas = document.getElementById('c');
    const _stage = document.getElementById('stage');
    const _ui = document.getElementById('ui');
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

    /* ── UI layout: keep controls in a right-side column ────────────────────
     * setUiLayout(...) is retained only so older generated payloads do not
     * crash. It deliberately cannot change the side, overlay state, or size.
     */
    function setUiLayout() {
      _autoUiLayout();
    }

    function _applyUiLayout(mode, sizePx) {
      const next = 'right';
      document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', `${sizePx}px`);
    }

    // Generated figures do not get to decide panel placement: a stable right
    // column prevents controls from covering the figure and avoids layout jumps.
    function _autoUiLayout() {
      const hasEditor = Boolean(_ui.querySelector('textarea'));
      const mode = 'right';
      const start = hasEditor ? 400 : 300;
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      const cap = Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      let size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', `${size}px`);
      let guard = 0;
      const step = () => {
        if (guard++ > 6) return;
        if (_ui.scrollHeight <= _ui.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', `${size}px`);
        requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    }

    // Re-evaluate when the generated code adds controls after first paint.
    new MutationObserver(() => {
      clearTimeout(_autoUiLayout._t);
      _autoUiLayout._t = setTimeout(_autoUiLayout, 0);
    }).observe(_ui, { childList: true, subtree: true });
    window.addEventListener('resize', () => { _autoUiLayout(); });

    /* ── Scene ───────────────────────────────────────────────────────────── */
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xffffff);

    /* ── Orthographic camera ─────────────────────────────────────────────── */
    const d = 3;                              // half-height in world units
    let aspect = canvas.clientWidth / canvas.clientHeight;
    let camera = new THREE.OrthographicCamera(
      -d * aspect, d * aspect, d, -d, 0.1, 100
    );
    camera.position.set(4, 4, 4);
    camera.lookAt(0, 0, 0);
    camera.updateProjectionMatrix();

    /* ── Controls ────────────────────────────────────────────────────────── */
    let controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Has the student orbited / panned / zoomed? OrbitControls fires 'start' on
    // pointer-down and on wheel — i.e. only on real user input — while the
    // 'change' event also fires from our own controls.update() in animate(),
    // so 'start' is the signal that does not produce false positives.
    // Consumed by the ResizeObserver: a camera the student has moved must NOT
    // be repositioned by a resize (chapter-preview iframes resize routinely).
    let _userMovedCamera = false;
    function _trackCameraInteraction(ctrl) {
      ctrl.addEventListener('start', () => { _userMovedCamera = true; });
    }
    _trackCameraInteraction(controls);

    // HOME view will be computed from the scene bounds so different scenes
    // (especially tall ones) get a consistent starting zoom/angle while
    // still allowing interactive OrbitControls.
    const HOME_POS = new THREE.Vector3();
    const HOME_TARGET = new THREE.Vector3(0, 0, 0);
    let HOME_ZOOM = 0.75;
    let _labelZoomRef = 1;      // zoom at which label scale is exactly 1
    let _lastViewArgs = null;   // last resolved setCameraView args, re-applied on resize

    document.getElementById('btnReset').addEventListener('click', () => {
      if (_lastViewArgs) { setCameraView(_lastViewArgs); return; }
      camera.position.copy(HOME_POS);
      controls.target.copy(HOME_TARGET);
      camera.zoom = HOME_ZOOM;
      camera.updateProjectionMatrix();
      controls.update();
    });

    // Framing parameters
    const FRAME_HALF_HEIGHT = d; // base frustum half-height used when computing zoom
    const FRAME_MARGIN = 0.08;   // fraction of extra space around content
    const MIN_ZOOM = 0.2;
    const MAX_ZOOM = 5;

    function computeSceneBounds() {
      const box = new THREE.Box3().setFromObject(scene);
      if (box.isEmpty()) {
        // fallback box so empty scenes get a sensible frame
        box.setFromCenterAndSize(new THREE.Vector3(0, 0, 0), new THREE.Vector3(2 * d, 2 * d, 2 * d));
      }
      const center = new THREE.Vector3();
      box.getCenter(center);
      const size = new THREE.Vector3();
      box.getSize(size);
      return { box, center, size };
    }

    /**
     * setCameraView(options)
     * - azimuthDeg: horizontal angle around Y axis, in degrees.
     * - elevationDeg: angle above the ground/XZ plane, in degrees.
     * - zoom: optional orthographic zoom. If omitted, derived from content bounds.
     * - target: optional [x,y,z] camera target. If omitted, uses scene bounds center.
     * - heightFraction: fraction of the view the content's height should occupy.
     * This is the preferred per-figure camera API for matching the source image.
     */
    /* ── Oblique projection ──────────────────────────────────────────────── */
    // An oblique projection is a shear of EYE-SPACE coordinates, applied before
    // the orthographic projection: P' = P_ortho · S. It is deliberately NOT a
    // shear of the geometry — keeping it in the camera means addLabel/_syncLabels
    // (which call pos.project(camera)) track it with no extra work.
    //
    // Known limitation: Raycaster.setFromCamera derives its ray direction from
    // the camera's view axis, not the sheared projection direction, so
    // registerInteractive hit-testing is approximate at large depth under
    // oblique. Acceptable for the shallow diagrams oblique is used for.
    let _obliqueState = null;        // { angleDeg, depthScale, shearAmt, shearTarget } or null

    function _applyObliqueShear() {
      if (!_obliqueState || !camera.isOrthographicCamera) return;
      const th = THREE.MathUtils.degToRad(_obliqueState.angleDeg);
      // shearAmt eases 1 -> 0 to reveal the true 3D shape. Both the shear terms
      // and the zt pinning terms below carry the same k, so the target plane
      // stays pinned and the figure does not drift while un-shearing.
      const k = _obliqueState.depthScale * _obliqueState.shearAmt;
      // Shear about the PROJECTION PLANE (the controls target's eye-space
      // depth zt), not about the camera origin. The camera looks down -Z with
      // the target at distance ~R, so every scene point has eye z ~= -R, not
      // ~= 0. Shearing raw z would add a large rigid translation
      // (cos(th)*k*R, sin(th)*k*R) to the ENTIRE scene, shoving it off-screen.
      // Shearing (z - zt) instead pins the target plane in place and only
      // tilts depth around it -- the textbook definition of an oblique
      // projection about the picture plane.
      camera.updateMatrixWorld();
      const zt = controls.target.clone().applyMatrix4(camera.matrixWorldInverse).z;
      const S = new THREE.Matrix4().set(
        1, 0, -Math.cos(th) * k, Math.cos(th) * k * zt,
        0, 1, -Math.sin(th) * k, Math.sin(th) * k * zt,
        0, 0, 1, 0,
        0, 0, 0, 1
      );
      // Post-multiply: S acts on eye space, then P_ortho projects.
      camera.projectionMatrix.multiply(S);
      camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();
    }

    // Re-apply the shear after ANY updateProjectionMatrix() — OrbitControls calls
    // it on every zoom, which would otherwise silently wipe the shear.
    function _installObliqueHook(cam) {
      if (cam.__obliqueHooked) return;
      const base = cam.updateProjectionMatrix.bind(cam);
      cam.updateProjectionMatrix = function () {
        base();
        _applyObliqueShear();
      };
      cam.__obliqueHooked = true;
    }

    function _setObliqueEnabled(on) {
      const btn = document.getElementById('btnProjToggle');
      if (on) {
        _obliqueState = _obliqueState || { angleDeg: 45, depthScale: 0.5, shearAmt: 1, shearTarget: 1 };
        _obliqueState.shearTarget = 1;
        if (btn) { btn.style.display = ''; btn.textContent = '3D view'; }
        // Oblique is only meaningful from its authored front-on pose. Setting
        // shearTarget BEFORE this call matters: setCameraView preserves the
        // current shearTarget rather than forcing it to 1, so the 1 set above is
        // what survives and drives the ease back to the printed view.
        if (_lastViewArgs) { setCameraView(_lastViewArgs); return; }
      } else if (_obliqueState) {
        // Keep the state object alive so animate() can ease shearAmt down to 0.
        // It is cleared only when setCameraView leaves the oblique projection.
        _obliqueState.shearTarget = 0;
        if (btn) btn.textContent = 'Figure view';
      }
      camera.updateProjectionMatrix();
      controls.update();
    }

    document.getElementById('btnProjToggle').addEventListener('click', () => {
      if (!_obliqueState) return;
      if (_obliqueState.shearTarget > 0.5) {
        _setObliqueEnabled(false);
      } else {
        _setObliqueEnabled(true);
      }
    });

    // Drag to reveal: past a small threshold, ease the shear out so the student
    // sees the true 3D object they are turning. The threshold separates a drag
    // from a click, so clicking an interactive element does not collapse the
    // figure.
    const _REVEAL_DRAG_PX = 6;
    let _revealPointerDown = false;
    let _revealDragPx = 0;
    let _revealLastX = 0;
    let _revealLastY = 0;

    canvas.addEventListener('pointerdown', (e) => {
      _revealPointerDown = true;
      _revealDragPx = 0;
      _revealLastX = e.clientX;
      _revealLastY = e.clientY;
    });
    window.addEventListener('pointerup', () => { _revealPointerDown = false; });
    canvas.addEventListener('pointermove', (e) => {
      if (!_revealPointerDown || !_obliqueState || _obliqueState.shearTarget === 0) return;
      // movementX/Y are unavailable in some environments; fall back to a
      // clientX/Y delta against the previous move so the accumulator never
      // goes NaN and silently disables drag-to-reveal.
      const _dx = typeof e.movementX === 'number' ? e.movementX : (e.clientX - _revealLastX);
      const _dy = typeof e.movementY === 'number' ? e.movementY : (e.clientY - _revealLastY);
      _revealLastX = e.clientX;
      _revealLastY = e.clientY;
      _revealDragPx += Math.abs(_dx) + Math.abs(_dy);
      if (_revealDragPx > _REVEAL_DRAG_PX) {
        _obliqueState.shearTarget = 0;
        const btn = document.getElementById('btnProjToggle');
        if (btn) btn.textContent = 'Figure view';
      }
    });

    /**
     * _ensureCamera(kind) → boolean
     * Rebuilds `camera` and `controls` when the required camera class changes.
     * OrbitControls caches its object, so it is disposed and reconstructed
     * rather than re-pointed. Returns true when a swap happened.
     */
    function _ensureCamera(kind) {
      const want = kind === 'perspective' ? 'perspective' : 'orthographic';
      const have = camera.isPerspectiveCamera ? 'perspective' : 'orthographic';
      if (want === have) return false;

      const prevTarget = controls.target.clone();
      controls.dispose();

      camera = want === 'perspective'
        ? new THREE.PerspectiveCamera(35, aspect, 0.1, 1000)
        : new THREE.OrthographicCamera(-d * aspect, d * aspect, d, -d, 0.1, 100);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.05;
      controls.target.copy(prevTarget);
      _trackCameraInteraction(controls);   // the old listener died with the old controls

      if (window.__figverify) {
        window.__figverify.camera = camera;
        window.__figverify.controls = controls;
      }
      return true;
    }

    // Solve an orthographic camera pose from the on-screen angles of the two
    // horizontal-plane axes, as measured off the source figure.
    //
    // For a camera at azimuth a, elevation e with up = (0,1,0):
    //     right = (  sin a,           0,      -cos a          )
    //     up'   = ( -cos a * sin e,   cos e,  -sin a * sin e   )
    // Projecting X=(1,0,0) and Z=(0,0,1) onto that basis and taking the angle
    // below screen horizontal gives:
    //     tan(phiX) = sin e * cot a
    //     tan(phiZ) = sin e * tan a
    // whose product and ratio invert cleanly:
    //     sin e = sqrt(tan phiX * tan phiZ)
    //     tan a = sqrt(tan phiZ / tan phiX)
    // Sanity: phiX = phiZ = 30 gives e = 35.264, a = 45 — canonical isometric.
    const ISO_FALLBACK = { azimuthDeg: 45, elevationDeg: 35.264389682754654 };

    function _solvePoseFromAxisAngles(angles) {
      // Explicit null means the source is drawn head-on: no depth to recover.
      if (angles === null) return { azimuthDeg: 90, elevationDeg: 0 };
      if (!angles || !Number.isFinite(angles.x) || !Number.isFinite(angles.z)) {
        return { ...ISO_FALLBACK };
      }
      // An axis at or past horizontal/vertical is drawn edge-on; the inversion
      // has no finite solution there.
      if (angles.x <= 0 || angles.x >= 90 || angles.z <= 0 || angles.z >= 90) {
        return { ...ISO_FALLBACK };
      }
      const tX = Math.tan(THREE.MathUtils.degToRad(angles.x));
      const tZ = Math.tan(THREE.MathUtils.degToRad(angles.z));
      const sinSq = tX * tZ;
      // sin^2(e) >= 1 admits no real elevation.
      if (!(sinSq > 0) || sinSq >= 1) return { ...ISO_FALLBACK };
      return {
        azimuthDeg: THREE.MathUtils.radToDeg(Math.atan(Math.sqrt(tZ / tX))),
        elevationDeg: THREE.MathUtils.radToDeg(Math.asin(Math.sqrt(sinSq))),
      };
    }

    function setCameraView({
      projection = 'orthographic',
      azimuthDeg: azimuthDegArg = 45,
      elevationDeg: elevationDegArg = 35,
      rollDeg = 0,
      obliqueAngleDeg = 45,
      depthScale = 0.5,
      zoom = null,
      target = null,
      heightFraction = 0.5,
      distanceScale = 1.2,
      axisScreenAngles = undefined
    } = {}) {
      let azimuthDeg = azimuthDegArg;
      let elevationDeg = elevationDegArg;
      // Measured axis angles win over any guessed azimuth/elevation. Oblique
      // overrides both below — its pose is fixed front-on by definition.
      if (axisScreenAngles !== undefined) {
        const solved = _solvePoseFromAxisAngles(axisScreenAngles);
        azimuthDeg = solved.azimuthDeg;
        elevationDeg = solved.elevationDeg;
      }
      const mode = projection === 'perspective' ? 'perspective'
        : projection === 'oblique' ? 'oblique'
          : 'orthographic';
      _ensureCamera(mode === 'perspective' ? 'perspective' : 'orthographic');
      _installObliqueHook(camera);
      if (mode === 'oblique') {
        // Preserve BOTH the in-flight shearAmt and the current shearTarget.
        // The ResizeObserver re-applies _lastViewArgs on every resize, and a
        // button click does not set _userMovedCamera — so hardcoding
        // shearTarget: 1 here would silently re-shear a figure the student had
        // already revealed. Task 3's "Figure view" button still works because it
        // sets shearTarget = 1 *before* calling setCameraView, and that value is
        // what gets preserved here.
        const _prevShearAmt = _obliqueState ? _obliqueState.shearAmt : 1;
        const _prevShearTarget = _obliqueState ? _obliqueState.shearTarget : 1;
        _obliqueState = {
          angleDeg: Number.isFinite(obliqueAngleDeg) ? obliqueAngleDeg : 45,
          depthScale: Number.isFinite(depthScale) ? depthScale : 0.5,
          shearAmt: _prevShearAmt,
          shearTarget: _prevShearTarget,
        };
        // Rotation stays enabled: dragging is how the student reveals the true
        // shape. The drag listener eases the shear out as they turn the figure.
        controls.enableRotate = true;
        const btn = document.getElementById('btnProjToggle');
        // Label reflects the PRESERVED shearTarget, not an assumed "just enabled"
        // state -- otherwise a resize while revealed (shearTarget 0) would flip
        // the label back to '3D view' even though the shear itself stayed put.
        if (btn) { btn.style.display = ''; btn.textContent = _prevShearTarget > 0.5 ? '3D view' : 'Figure view'; }
      } else {
        _obliqueState = null;
        controls.enableRotate = true;
        const btn = document.getElementById('btnProjToggle');
        if (btn) btn.style.display = 'none';
      }

      const { box, center, size } = computeSceneBounds();
      const viewTarget = Array.isArray(target)
        ? new THREE.Vector3(target[0] || 0, target[1] || 0, target[2] || 0)
        : center;

      // Oblique is defined by a front-on viewpoint; depth comes from the shear.
      if (mode === 'oblique') { azimuthDeg = 90; elevationDeg = 0; }

      const radius = Math.max(size.length() * distanceScale, FRAME_HALF_HEIGHT * 2);
      const azimuth = THREE.MathUtils.degToRad(azimuthDeg);
      const elevation = THREE.MathUtils.degToRad(elevationDeg);
      const cosElev = Math.cos(elevation);
      const dir = new THREE.Vector3(
        Math.cos(azimuth) * cosElev,
        Math.sin(elevation),
        Math.sin(azimuth) * cosElev
      ).normalize();

      camera.position.copy(dir).multiplyScalar(radius).add(viewTarget);
      camera.up.set(0, 1, 0);
      if (Number.isFinite(rollDeg) && rollDeg !== 0) {
        camera.up.applyAxisAngle(dir.clone().negate(), THREE.MathUtils.degToRad(rollDeg));
      }
      camera.lookAt(viewTarget);
      camera.updateMatrixWorld();

      // Project all 8 bounding-box corners into view space. View-space X and Y
      // are independent of how far the camera sits along its own view axis, so
      // this extent is valid for both projections.
      const toView = camera.matrixWorldInverse;
      const pt = new THREE.Vector3();
      // Under oblique, camera.projectionMatrix will get a depth shear baked in
      // (about the target's eye-space depth, see _applyObliqueShear) AFTER
      // this fit runs. If the fit measured the UNsheared extent, the shear
      // would inflate the actually-drawn projection beyond what was fit,
      // breaking heightFraction (and, at large heightFraction, clipping the
      // figure off-screen). So replicate the same shear here before measuring.
      const obliqueTh = mode === 'oblique' ? THREE.MathUtils.degToRad(_obliqueState.angleDeg) : 0;
      const obliqueK = mode === 'oblique' ? _obliqueState.depthScale * _obliqueState.shearAmt : 0;
      const ztFit = mode === 'oblique' ? viewTarget.clone().applyMatrix4(toView).z : 0;
      let minVY = Infinity, maxVY = -Infinity, minVX = Infinity, maxVX = -Infinity;
      for (let xi = 0; xi < 2; xi++) for (let yi = 0; yi < 2; yi++) for (let zi = 0; zi < 2; zi++) {
        pt.set(xi ? box.max.x : box.min.x,
          yi ? box.max.y : box.min.y,
          zi ? box.max.z : box.min.z).applyMatrix4(toView);
        let vx = pt.x, vy = pt.y;
        if (mode === 'oblique') {
          const dz = pt.z - ztFit;
          vx -= Math.cos(obliqueTh) * obliqueK * dz;
          vy -= Math.sin(obliqueTh) * obliqueK * dz;
        }
        minVY = Math.min(minVY, vy); maxVY = Math.max(maxVY, vy);
        minVX = Math.min(minVX, vx); maxVX = Math.max(maxVX, vx);
      }
      const projH = Math.max(maxVY - minVY, 1e-6);
      const projW = Math.max(maxVX - minVX, 1e-6);
      const frac = Math.min(Math.max(heightFraction, 0.05), 1);

      if (camera.isPerspectiveCamera) {
        // Frame by DISTANCE and fov. Assigning an orthographic-derived number to
        // camera.zoom (the old behaviour) is dimensionally meaningless here.
        camera.zoom = 1;
        camera.aspect = aspect;
        const vFov = THREE.MathUtils.degToRad(camera.fov);
        const hFov = 2 * Math.atan(Math.tan(vFov / 2) * aspect);
        const distH = (projH / 2) / Math.tan(vFov / 2) / frac;
        const distW = (projW / 2) / Math.tan(hFov / 2) / frac;
        const dist = Math.max(distH, distW, 0.01);
        camera.position.copy(dir).multiplyScalar(dist).add(viewTarget);
        camera.lookAt(viewTarget);
        camera.near = Math.max(0.01, dist - radius * 2);
        camera.far = dist + radius * 4;
      } else {
        camera.near = 0.01;
        camera.far = radius * 4 + 100;
        let resolvedZoom;
        if (Number.isFinite(zoom)) {
          resolvedZoom = zoom;
        } else {
          const zH = (2 * FRAME_HALF_HEIGHT * frac) / projH;
          const zW = (2 * FRAME_HALF_HEIGHT * aspect * frac) / projW;
          resolvedZoom = Math.min(Math.max(Math.min(zH, zW), MIN_ZOOM), MAX_ZOOM);
        }
        camera.zoom = resolvedZoom;
      }

      controls.target.copy(viewTarget);
      camera.updateProjectionMatrix();
      controls.update();

      HOME_POS.copy(camera.position);
      HOME_TARGET.copy(controls.target);
      HOME_ZOOM = camera.zoom;

      _labelZoomRef = camera.zoom || 1;
      // An explicit setCameraView (including the Reset View button) is the
      // author/student asking for this exact pose, so any earlier manual
      // orbiting is superseded — resize may re-fit freely again.
      _userMovedCamera = false;
      _lastViewArgs = {
        projection: mode, azimuthDeg, elevationDeg, rollDeg,
        obliqueAngleDeg, depthScale, zoom, target, heightFraction, distanceScale,
        axisScreenAngles,
      };

      window.__figureCameraView = {
        projection: mode,
        azimuthDeg, elevationDeg, rollDeg,
        zoom: camera.zoom,
        target: [controls.target.x, controls.target.y, controls.target.z],
      };
    }

    /**
     * setStandardView(options)
     * Backwards-compatible wrapper. Prefer setCameraView({ azimuthDeg, elevationDeg, ... }).
     */
    function setStandardView({ azimuth = Math.PI / 4, polar = Math.PI / 4, heightFraction = 0.5 } = {}) {
      const azimuthDeg = THREE.MathUtils.radToDeg(azimuth);
      const elevationDeg = 90 - THREE.MathUtils.radToDeg(polar);
      setCameraView({ azimuthDeg, elevationDeg, heightFraction });
    }

    // Apply a standard view once at startup so tall/narrow scenes get a similar framing.
    // Call this again after adding or loading scene content that changes bounds.
    setStandardView();

    /* ── Label system ────────────────────────────────────────────────────── */
    const _labels = [];
    const _v = new THREE.Vector3();

    /**
     * addLabel(text, position3D, options?) → entry
     *   text     : HTML string  ('x<sub>1</sub>', '&lambda;', '<b>bold</b>', …)
     *   position : THREE.Vector3 (world space)
     *   options  : {
     *       color     : css color string  (default '#111')
     *       fontSize  : css string        (default '13px')
     *       bold      : boolean           (default false)
     *       offset    : [dx, dy] pixels   (default [0, 0])
     *       background: css string        (default 'none')
     *     }
     *   Returns an entry object; update entry.pos.set(x,y,z) to reposition.
     */
    function addLabel(text, position, options = {}) {
      const div = document.createElement('div');
      div.className = 'lbl';
      div.innerHTML = text;
      if (options.color) div.style.color = options.color;
      if (options.fontSize) div.style.fontSize = options.fontSize;
      if (options.bold) div.style.fontWeight = 'bold';
      if (options.background) {
        div.style.background = options.background;
        div.style.padding = '1px 4px';
        div.style.borderRadius = '3px';
      }
      // #stage, not <body>: _syncLabels below computes left/top in canvas pixel
      // space, which is only the same as page space while the stage starts at the
      // page origin. Once #ui is docked it does not, so labels must be positioned
      // inside the stage.
      _stage.appendChild(div);
      const entry = { div, pos: position.clone(), offset: options.offset || [0, 0] };
      _labels.push(entry);
      return entry;
    }

    const _referenceDistance = 8;

    function _syncLabels() {
      for (const { div, pos, offset } of _labels) {
        _v.copy(pos).project(camera);

        // Hide labels that are behind the camera or outside the normalized device
        // coordinate cube to avoid showing offscreen labels.
        if (_v.z > 1 || _v.z < -1 || _v.x < -1 || _v.x > 1 || _v.y < -1 || _v.y > 1) {
          div.style.display = 'none';
          continue;
        }
        div.style.display = '';

        const ox = offset && offset[0] ? offset[0] : 0;
        const oy = offset && offset[1] ? offset[1] : 0;
        const x = canvas.offsetLeft + (_v.x * 0.5 + 0.5) * canvas.clientWidth + ox;
        const y = canvas.offsetTop + (-_v.y * 0.5 + 0.5) * canvas.clientHeight + oy;

        // Under a parallel projection (orthographic and oblique) camera distance
        // has NO effect on apparent size — only zoom does. Folding distance in
        // made label sizes vary with scene size across figures.
        let scale;
        if (camera.isOrthographicCamera) {
          scale = (camera.zoom || 1) / (_labelZoomRef || 1);
        } else {
          const distance = Math.max(camera.position.distanceTo(pos), 1e-4);
          scale = _referenceDistance / distance;
        }

        // Clamp scale to a reasonable range to avoid extremely small/large labels.
        scale = Math.max(0.15, Math.min(scale, 6));

        div.style.left = x + 'px';
        div.style.top = y + 'px';
        div.style.transform = `translate(-50%, -50%) scale(${scale})`;
      }
    }

    /* ── Interaction explainer helpers ───────────────────────────────────── */
    const _tooltip = document.getElementById('figTooltip');
    const _raycaster = new THREE.Raycaster();
    const _pointer = new THREE.Vector2();
    const _interactiveObjects = [];
    let _hoveredInteractive = null;

    function showPopup(title, body) {
      window.parent.postMessage({ type: 'alex-popup', title, body }, '*');
    }

    function hidePopup() {
      window.parent.postMessage({ type: 'alex-popup', title: null }, '*');
    }

    function showTooltip(text, event) {
      if (!_tooltip || !text) return;
      _tooltip.textContent = text;
      _tooltip.style.display = 'block';
      moveTooltip(event);
    }

    function moveTooltip(event) {
      if (!_tooltip || _tooltip.style.display === 'none') return;
      const pad = 12;
      const x = Math.min(event.clientX + pad, window.innerWidth - _tooltip.offsetWidth - pad);
      const y = Math.max(pad, event.clientY - _tooltip.offsetHeight - pad);
      _tooltip.style.left = x + 'px';
      _tooltip.style.top = y + 'px';
    }

    function hideTooltip() {
      if (_tooltip) _tooltip.style.display = 'none';
    }

    function _setPointerFromEvent(event) {
      const rect = canvas.getBoundingClientRect();
      _pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      _pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    }

    function _firstInteractiveHit(event) {
      if (!_interactiveObjects.length) return null;
      _setPointerFromEvent(event);
      _raycaster.setFromCamera(_pointer, camera);
      const hits = _raycaster.intersectObjects(_interactiveObjects.map(entry => entry.object), true);
      for (const hit of hits) {
        let obj = hit.object;
        while (obj) {
          const entry = _interactiveObjects.find(item => item.object === obj);
          if (entry) return { ...entry, hit };
          obj = obj.parent;
        }
      }
      return null;
    }

    function registerInteractive(object, info = {}) {
      if (!object) return object;
      object.userData = object.userData || {};
      object.userData.interactive = true;
      _interactiveObjects.push({ object, info });
      return object;
    }

    canvas.addEventListener('pointermove', (event) => {
      moveTooltip(event);
      const entry = _firstInteractiveHit(event);
      if (entry) {
        _hoveredInteractive = entry;
        canvas.style.cursor = 'pointer';
        showTooltip(entry.info.tooltip || entry.info.title || 'Click to explain', event);
      } else {
        _hoveredInteractive = null;
        canvas.style.cursor = controls.enabled ? 'grab' : 'default';
        hideTooltip();
      }
    });

    canvas.addEventListener('pointerleave', () => {
      _hoveredInteractive = null;
      canvas.style.cursor = 'default';
      hideTooltip();
    });

    canvas.addEventListener('click', (event) => {
      const entry = _firstInteractiveHit(event) || _hoveredInteractive;
      if (!entry) {
        hidePopup();
        return;
      }
      const title = entry.info.title || entry.info.tooltip || 'Figure element';
      const body = entry.info.body || entry.info.description || 'This part is interactive.';
      showPopup(title, body);
      if (typeof entry.info.onClick === 'function') entry.info.onClick(entry.hit, entry.object);
    });

    window.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        hidePopup();
        hideTooltip();
      }
    });

    /* ── Render loop ─────────────────────────────────────────────────────── */
    let _firstFrame = true;
    let _lastFrameTime = performance.now();
    function animate() {
      requestAnimationFrame(animate);
      // Ease the oblique shear toward its target. Frame-rate normalised against
      // 60fps and clamped, so the reveal takes the same wall-clock time on a
      // slow headless renderer as on a fast display.
      const _now = performance.now();
      const _frameScale = Math.min(2.5, Math.max(0.5, (_now - _lastFrameTime) / 16));
      _lastFrameTime = _now;
      if (_obliqueState) {
        const _tgt = _obliqueState.shearTarget;
        if (Math.abs(_obliqueState.shearAmt - _tgt) > 0.001) {
          _obliqueState.shearAmt += (_tgt - _obliqueState.shearAmt) * Math.min(1, 0.14 * _frameScale);
          camera.updateProjectionMatrix();
        } else if (_obliqueState.shearAmt !== _tgt) {
          _obliqueState.shearAmt = _tgt;
          camera.updateProjectionMatrix();
        }
      }
      controls.update();
      renderer.render(scene, camera);
      _syncLabels();
      // Frame counter used by the headless verifier to prove the render loop is
      // actually alive (not frozen by an exception thrown after the first frame).
      window.__figFrames = (window.__figFrames || 0) + 1;
      if (_firstFrame) { _firstFrame = false; window.__markRendered?.(); }
    }
    animate();

    /* ── Verification hook (invisible; read by the headless verifier) ──────── */
    // Exposes the live objects so automated checks can confirm the GPU drew
    // something, the scene has content, and no geometry has NaN coordinates.
    window.__figverify = {
      renderer, scene, camera, controls, setCameraView,
      obliqueState: () => _obliqueState,
    };

    /* ── Resize (ResizeObserver on canvas) ───────────────────────────────── */
    new ResizeObserver(() => {
      const w = canvas.clientWidth, h = canvas.clientHeight;
      if (!w || !h) return;
      aspect = w / h;
      renderer.setSize(w, h, false);
      if (camera.isPerspectiveCamera) {
        camera.aspect = aspect;
      } else {
        camera.left = -d * aspect;
        camera.right = d * aspect;
      }
      // updateProjectionMatrix() is hooked (see _installObliqueHook), so the
      // oblique shear is re-applied here on BOTH branches below.
      camera.updateProjectionMatrix();
      // Re-apply the last view so heightFraction still holds at the new aspect —
      // but ONLY while the camera is still the one the figure authored. Once the
      // student has orbited/panned/zoomed, setCameraView would recompute
      // camera.position from azimuth/elevation and overwrite controls.target,
      // silently throwing away their interaction on every canvas resize (and
      // chapter-preview iframes resize routinely). In that case we keep the live
      // pose and only widen/narrow the frustum, which is all a resize means.
      if (_lastViewArgs && !_userMovedCamera) setCameraView(_lastViewArgs);
      else controls.update();
    }).observe(canvas);

    /* ── Expression parsing ──────────────────────────────────────────────── */
    /**
     * compileExpr(src, vars) → (…args) => number
     * Throws on a syntax error or a variable outside `vars`. Never falls back.
     *
     * DUPLICATED (deliberately): base_scene_2d.html has a byte-for-byte
     * equivalent ES5 copy. Each scaffold is a standalone served HTML file and
     * neither can import the other, so behaviour changes must be made TWICE.
     * Keep this in sync with compileExpr in base_scene_2d.html.
     */
    function compileExpr(src, vars) {
      if (!window.exprEval || !window.exprEval.Parser) {
        throw new Error('Expression parser unavailable (expr-eval CDN did not load)');
      }
      const names = (vars && vars.length) ? vars : ['x'];
      let parsed;
      try {
        parsed = new window.exprEval.Parser().parse(String(src));
      } catch (e) {
        throw new Error(`Cannot parse "${src}": ${e?.message || e}`);
      }
      for (const used of parsed.variables()) {
        if (!names.includes(used)) {
          throw new Error(`Unknown variable "${used}" (expected: ${names.join(', ')})`);
        }
      }
      return (...args) => {
        const scope = {};
        names.forEach((n, i) => { scope[n] = args[i]; });
        let v;
        try { v = parsed.evaluate(scope); } catch { return NaN; }
        return typeof v === 'number' ? v : NaN;
      };
    }

    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs directly in #ui, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_2d.html.
     */
    function _equationErrorSlot(input) {
      const parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        const slotId = `eq-err-${input.id}`;
        const byId = document.getElementById(slotId);
        if (byId) return byId;
        const namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      const existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      const span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → (fn, src) => void
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify.js catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_2d.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') return (fn, src) => t(fn, src);
      if (t && t.handle) {
        const method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            `bindEquationInput("${inputId}"): target handle has no method "${method}". ` +
            `Use { handle, method: '...' } with a method the handle really has ` +
            `(plotCurve3D/plotSurface: setExpr, setFn; plotParametric3D: setX, setY, setZ).`
          );
        }
        return (fn) => t.handle[method](fn);
      }
      if (t && typeof t.setFn === 'function') return (fn) => t.setFn(fn);
      throw new Error(
        `bindEquationInput("${inputId}"): this target cannot be driven — it is not a ` +
        `function and has no .setFn. Handles without .setFn (e.g. plotParametric3D) must ` +
        `be passed as { handle, method: 'setX' } naming the setter to call.`
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     * targets: a plot handle, { handle, method }, a function(fn, src), or an array.
     * opts   : { variables=['x'], onChange(fn, src) }
     * On a parse error the last good geometry is kept and the message is shown
     * inline. This NEVER substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_2d.html.
     */
    function bindEquationInput(inputId, targets, opts = {}) {
      const input = document.getElementById(inputId);
      if (!input) throw new Error(`bindEquationInput: no element with id "${inputId}"`);
      const vars = opts.variables || ['x'];
      const list = Array.isArray(targets) ? targets : [targets];
      const slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      const appliers = list.map((t) => _resolveEqTarget(inputId, t));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          const fn = compileExpr(src, vars);
          for (const run of appliers) run(fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', () => apply(input.value));
      apply(input.value);
      return { apply, input, errorSlot: slot };
    }

    /* ── 3D plotting ─────────────────────────────────────────────────────── */
    const _plot3d = new Map();

    function _disposeObject(obj) {
      obj.traverse?.(o => {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
        else o.material?.dispose?.();
      });
    }

    function _register3d(id, handle) {
      const prev = _plot3d.get(id);
      if (prev && prev !== handle) { scene.remove(prev.object); _disposeObject(prev.object); }
      _plot3d.set(id, handle);
      return handle;
    }

    function _resolveFn3d(value, vars) {
      return typeof value === 'function' ? value : compileExpr(value, vars);
    }

    /**
     * plotCurve3D(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain=[-2,2], plane='xy'|'xz',
     *           samples=200, color=0x1f77b4 }
     * 'xy' maps t → (t, f(t), 0); 'xz' maps t → (t, 0, f(t)).
     */
    function plotCurve3D(id, opts = {}) {
      const vars = opts.variables || ['x'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || [-2, 2],
        samples: opts.samples || 200,
        plane: opts.plane === 'xz' ? 'xz' : 'xy',
        setExpr(src) { this.fn = _resolveFn3d(src, vars); return this.sample(); },
        setFn(f) { this.fn = f; return this.sample(); },
        setDomain(dm) { this.domain = dm; return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          if (!this.fn) return this;
          const [a, b] = this.domain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let v;
            try { v = this.fn(t); } catch { v = NaN; }
            if (!Number.isFinite(v)) v = 0;
            pts.push(this.plane === 'xz' ? new THREE.Vector3(t, 0, v)
              : new THREE.Vector3(t, v, 0));
          }
          const old = line.geometry;
          line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    /**
     * plotParametric3D(id, opts) → handle
     *   opts: { x, y, z, variables=['t'], tDomain=[0,1], samples=200, color }
     */
    function plotParametric3D(id, opts = {}) {
      const vars = opts.variables || ['t'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fx: _resolveFn3d(opts.x ?? '0', vars),
        fy: _resolveFn3d(opts.y ?? '0', vars),
        fz: _resolveFn3d(opts.z ?? '0', vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX(src) { this.fx = _resolveFn3d(src, vars); return this.sample(); },
        setY(src) { this.fy = _resolveFn3d(src, vars); return this.sample(); },
        setZ(src) { this.fz = _resolveFn3d(src, vars); return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          const [a, b] = this.tDomain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let x, y, z;
            try { x = this.fx(t); y = this.fy(t); z = this.fz(t); } catch { x = y = z = NaN; }
            if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(z)) {
              pts.push(new THREE.Vector3(x, y, z));
            }
          }
          const old = line.geometry;
          line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    /**
     * plotSurface(id, opts) → handle
     *   opts: { expr | fn, variables=['x','y'], xDomain=[-2,2], yDomain=[-2,2],
     *           segments=48, color=0x6699cc, wireframe=false }
     * Height is mapped to the world Y axis (the scaffold is y-up); the domain
     * spans world X and Z.
     */
    function plotSurface(id, opts = {}) {
      const vars = opts.variables || ['x', 'y'];
      const material = new THREE.MeshBasicMaterial({
        color: opts.color ?? 0x6699cc,
        wireframe: !!opts.wireframe,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: opts.opacity ?? 0.85,
      });
      const mesh = new THREE.Mesh(new THREE.BufferGeometry(), material);
      scene.add(mesh);
      const handle = {
        id,
        object: mesh,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        xDomain: opts.xDomain || [-2, 2],
        yDomain: opts.yDomain || [-2, 2],
        segments: opts.segments || 48,
        setExpr(src) { this.fn = _resolveFn3d(src, vars); return this.sample(); },
        setFn(f) { this.fn = f; return this.sample(); },
        remove() { scene.remove(mesh); _disposeObject(mesh); _plot3d.delete(id); },
        sample() {
          if (!this.fn) return this;
          const [x0, x1] = this.xDomain;
          const [y0, y1] = this.yDomain;
          const seg = Math.max(1, this.segments | 0);
          const geom = new THREE.PlaneGeometry(x1 - x0, y1 - y0, seg, seg);
          const pos = geom.attributes.position;
          const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
          for (let i = 0; i < pos.count; i++) {
            const px = pos.getX(i) + cx;
            const py = pos.getY(i) + cy;
            let h;
            try { h = this.fn(px, py); } catch { h = NaN; }
            if (!Number.isFinite(h)) h = 0;
            pos.setXYZ(i, px, h, py);
          }
          pos.needsUpdate = true;
          geom.computeVertexNormals();
          geom.computeBoundingBox();
          geom.computeBoundingSphere();
          const old = mesh.geometry;
          mesh.geometry = geom;
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();

  </script>
</body>

</html>
--------------------------------------------------------------------------------

WHAT THE SCAFFOLD PROVIDES (already defined — use these, never re-declare them):
- Scale guide (orthographic camera, d=3 frustum half-height): keep main geometry within ±2 units in all axes. Typical sizes: cube side 1–2 units, arrow length 1–2, plane width 2–4, sphere radius 0.05–0.15.
- setCameraView({ projection, azimuthDeg, elevationDeg, rollDeg, axisScreenAngles, obliqueAngleDeg, depthScale, zoom, target, heightFraction, distanceScale }) — source-matched camera setup.
  heightFraction: fraction of viewport height the content should fill (default 0.5; use 0.65–0.75 to fill more). Omit zoom — the scaffold auto-fits from projected scene bounds.
  Call it AFTER all geometry is in the scene, or auto-fit measures the wrong bounds. Labels come afterwards and do not affect the fit.
- #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel.
- addLabel(htmlString, THREE.Vector3, options?) — floating HTML label system.
- registerInteractive(object, { title, body, tooltip }), showPopup(title, body), hidePopup, showTooltip, hideTooltip — hover/click explanations.
- compileExpr(src, vars) → f(...args); throws on a bad expression (never returns a fallback)
- bindEquationInput(inputId, targets, { variables, onChange }) — wires an <input> to plot handles; shows parse errors inline
- plotCurve3D(id, { expr, variables, domain, plane:'xy'|'xz', samples, color }) → handle
- plotParametric3D(id, { x, y, z, variables, tDomain, samples, color }) → handle
- plotSurface(id, { expr, variables, xDomain, yDomain, segments, color }) → handle
  variables: the argument names the expression may use, in order (defaults: plotCurve3D ['x'], plotParametric3D ['t'], plotSurface ['x','y']). When a plan field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotCurve3D('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  Handles re-sample on EVERY setter call, and the setters differ: plotCurve3D → .setExpr / .setFn / .setDomain · plotParametric3D → .setX / .setY / .setZ · plotSurface → .setExpr / .setFn. All handles also have .sample() and .remove().
- Also pre-wired, do not re-declare: _labels, _syncLabels, animate, renderer, scene, camera, controls, d, aspect, setStandardView.

FIGURE RULES:
- Every visible element must be constructed as Three.js geometry (meshes, lines, points, sprites). Do NOT reproduce the figure as a texture, canvas drawing, or flat PlaneGeometry with the image drawn on it — pasting the original image onto a plane is never a valid solution.
- Keep the background white (#ffffff).
- The output should look recognizably like the source figure — same general geometry, viewpoint, labels, and proportions. It does not need to be a pixel-perfect same-size replacement.
- CAMERA / VIEW: camera pose is a standard default per projection mechanism, and PROJECTION TYPE in the user message gives the exact setCameraView call. Do not spend effort inferring exact angles from the source — spend it on ELEMENTS, geometry, and interactions. Align key visual anchors (object center, axes, labels) to similar relative positions as the source so the first frame is recognizable. You may adjust controls.target, object scale, and projection parameters; prefer setCameraView over setting camera.zoom directly, and if you do set zoom manually call camera.updateProjectionMatrix().
- Add ALL visible text labels with addLabel. Missing or wrong labels are a critical failure; match the source's font sizes and let placement reinforce depth.
- Interactions can be any type that serves the concept: sliders, buttons, panels, animations, step controls, hover/click, or direct 3D manipulation. Controls, panels, and UI affordances are welcome where they genuinely aid understanding — avoid decorative or redundant ones, but do not artificially restrict the type or amount of interaction.

ORDER OF WORK:
1) Settle the projection mechanism and pose from the plan BEFORE speccing any geometry — projection decides which edges stay parallel, which faces foreshorten, and what angle depth lines leave at.
2) Spec every element's Three.js primitive as one inline comment per element at the top of your JS block, e.g.
     // pinhole → SphereGeometry(0.07)  black
     // ray     → Line  dashed  grey
   Then build exactly that spec — do not deviate from it.
3) Build the static geometry. Preserve relative scale, spacing, depth ordering, and occlusion.
4) VERIFY before moving on: re-check what you built against GEOMETRY NOTES and the source image, element by element — position, orientation, proportions, and shape, not just presence. Fix any mismatch now; a generic-but-plausible arrangement that skips this check is the most common way geometry ends up wrong.
5) Then, in this order: setCameraView(...) → all labels → the plan's interactions.

userContent.text:
CONTEXT FROM TEXTBOOK:
This figure illustrates the named components and coordinate geometry of the pinhole camera model. A box representing the camera body is shown in 3D, with the pinhole/camera center marked as a black dot on its rear face. From this center, three axes extend: Z along the optical axis pointing forward, Y pointing upward, and X pointing laterally, forming a right-handed coordinate frame. The projection plane is labeled on the front face of the box, and the focal length f is indicated in red as the distance from that plane back to the pinhole. This figure establishes the standard naming conventions — optical center, optical axis, projection plane, and focal length — that underpin all subsequent formulations of perspective projection.

PROJECTION TYPE: oblique
Call setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction }) after all geometry is added — a standard cabinet-oblique pose; the plan does not measure per-figure oblique angles. The scaffold implements oblique as a shear of the eye-space projection matrix, so the front face stays undistorted, depth edges leave at obliqueAngleDeg, and labels track the shear automatically. Build the TRUE 3D object — the shear is the camera's job. Do NOT shear geometry, do NOT wrap the figure in a sheared parent Object3D, and do NOT disable automatic matrix updates. The scaffold also provides the reveal interaction: dragging eases the shear out to expose the real 3D shape and a toggle button returns to the printed view — do not implement either yourself.
AXIS ASSIGNMENT: the pose is pinned, so in BoxGeometry(w, h, d) the w axis is screen-right, h is screen-up, and d is the receding diagonal. Before writing each BoxGeometry, look at the source image and decide which of the object's dimensions actually recedes there — do not assume it is the one the domain calls "depth". In feature-map / layer-stack diagrams the channel count is usually the w (horizontal) extent along the flow direction and a spatial dimension is d. Sanity-check the silhouette against the source: a block that should read as a long bar pointing at its neighbours must be long in w, not in d, or it will render as a sliver shooting into the page. If GEOMETRY NOTES assigns the axes in a way that contradicts the source image's silhouette, follow the image.

ELEMENTS TO RECREATE IN 3D:
  - Rectangular camera-body box (long axis horizontal on screen, lying to the LEFT of the origin along -Z)
  - Near side face of the box (x = -1 plane), filled light olive-grey — the large true-shaped rectangle at lower left
  - Top face of the box (y = +1 plane), filled pale blue-grey, receding up-right
  - Rear face of the box at z = 0, filled dark olive-green, standing vertically at the right end of the box
  - Front face of the box at z = -f: the PROJECTION / IMAGE PLANE, translucent olive, outlined with dashed lines
  - Dashed hidden edges: vertical far-left edge, diagonal hidden bottom edge running up-right, vertical hidden top-rear edge
  - Black filled ellipse (pinhole / camera centre) at the world origin, centred on the dark rear face
  - Y axis: black arrow from the origin straight up, label 'Y' at its tip
  - X axis: black arrow from the origin diagonally up-right (the receding depth direction), label 'X' at its tip
  - Z axis: black arrow from the origin horizontally right (out of the camera, along the optical axis), label 'Z' below its tip
  - Red double-headed arrow under the box spanning the box length, labelled italic 'f' (focal length)
  - Title text 'Pinhole camera' (upper left) and 'World coordinates' (upper right)
  - Grey annotation label 'Projection plane' with curved grey arrow pointing to the left end of the box
  - Grey annotation label 'Optical / principal axis' with grey arrow pointing down-left onto the Z arrow
  - Grey annotation label 'Pinhole / camera center' with grey arrow pointing up-left onto the black dot

GEOMETRY NOTES (world-space scale, color palette, and any formula/value needed for correctness — build to these so sizes, zoom, and colors match the source; do not guess dimensions the notes already specify):
World frame: origin = pinhole/camera centre. +Z is screen-right (horizontal, out of the camera toward the scene), +Y is screen-up, +X is the receding diagonal drawn up-right at roughly 50° from horizontal (oblique depth direction). Camera box: X × Y × Z = 2 × 2 × f world units, spanning x∈[-1,1], y∈[-1,1], z∈[-f, 0]; default f = 2.3 (source shows box length ≈ 1.15× its height). Axis arrows all start exactly at the origin: Y arrow length ≈ 3.4 up, X arrow length ≈ 2.6 along the up-right diagonal, Z arrow length ≈ 4.5 to the right (it must extend well past the box, about twice the box length). Pinhole is a black filled ellipse ~0.18 × 0.32 units, centred at the origin on the dark rear face (z = 0). Faces / colours read from source: near side face x = -1 light olive-grey #A7AD8C (this is the big true-shaped rectangle at lower-left, width = f, height = 2); top face y = +1 pale blue-grey #AEB7BB; rear face z = 0 dark olive-green #46503C (the vertical panel at the right end, carrying the pinhole); front face z = -f = the projection plane, translucent olive #A7AD8C at ~45% opacity with dashed dark-grey (#3C4A44) outline. Hidden edges dashed in #3C4A44: the vertical edge at (x=-1, z=-f), the bottom edge at (y=-1, z=-f) running up-right, and the top-rear hidden edge. Red focal-length indicator #FF0000: double-headed arrow drawn just below the box bottom (y ≈ -1.35) running from z = -f to z = 0, with italic 'f' centred beneath it. Text labels black serif: 'Pinhole camera' top-left, 'World coordinates' top-right, axis letters X/Y/Z at arrow tips. Grey (#7E9195) annotation text + leader arrows: 'Projection plane' at left pointing with a curved arrow to the left end of the box, 'Optical / principal axis' at right pointing down-left onto the Z arrow, 'Pinhole / camera center' at lower right pointing up-left onto the black dot. Projection maths for the click/slider readouts: image point (x, y) = (f·X/Z, f·Y/Z); moving f only rescales the image, the ray directions through the camera centre are unchanged. Left-handed toggle negates the Y axis (arrow flips to point down) and negates the sign of the image y coordinate.

DISCRETE CONTROLS (implement every one of these in #ui, each must work independently):
[
  {
    "id": "orbitScene",
    "type": "orbit",
    "teaches": "that the camera body, the image plane at distance f behind the pinhole, and the three axes form one rigid 3D frame rather than a flat diagram"
  },
  {
    "id": "labelTour",
    "type": "state",
    "label": "Name the parts",
    "states": [
      "none",
      "Z / optical axis",
      "Y axis",
      "X axis",
      "projection plane",
      "pinhole / camera centre",
      "all labels"
    ],
    "default": "none"
  },
  {
    "id": "handedness",
    "type": "toggle",
    "label": "Coordinate convention",
    "options": [
      "Right-handed (X right, Y up, Z forward)",
      "Left-handed (Y flipped down)"
    ],
    "default": "Right-handed (X right, Y up, Z forward)"
  },
  {
    "id": "focalLength",
    "type": "slider",
    "label": "Focal length f",
    "range": [
      0.6,
      4,
      0.1
    ],
    "default": 2.3
  },
  {
    "id": "pickComponent",
    "type": "click",
    "teaches": "the role each named part plays in the projection equations x = f·X/Z, y = f·Y/Z — clicking the optical centre, optical axis, projection plane or the f arrow highlights it and shows the term it controls"
  }
]

DEMO STEPS (tween through these using goToStep(); each step drives the controls above):
[
  {
    "title": "The camera body",
    "narration": "A rectangular camera box sits along the negative Z direction. Its rear wall carries a tiny hole at the world origin; light entering there falls on the plane at the far end of the box.",
    "state": {
      "labelTour": "none",
      "focalLength": 2.3,
      "handedness": "Right-handed (X right, Y up, Z forward)"
    }
  },
  {
    "title": "Optical axis and camera centre",
    "narration": "Z points out of the pinhole into the scene: this is the optical or principal axis, and the pinhole itself is the camera centre — the single point every ray passes through.",
    "state": {
      "labelTour": "Z / optical axis",
      "focalLength": 2.3
    }
  },
  {
    "title": "Completing the right-handed frame",
    "narration": "Y points up and X points laterally, so X × Y = Z: the standard right-handed world frame anchored at the camera centre.",
    "state": {
      "labelTour": "X axis",
      "focalLength": 2.3
    }
  },
  {
    "title": "Projection plane and focal length",
    "narration": "The image forms on the projection plane at the far end of the box, a distance f behind the pinhole. Drag f and watch the plane move: a longer f magnifies the image, since x = f·X/Z.",
    "state": {
      "labelTour": "projection plane",
      "focalLength": 3.4
    }
  },
  {
    "title": "Right- vs left-handed convention",
    "narration": "Flipping Y to point down gives the left-handed convention used by many image-coordinate systems; the same 3D point now maps to an image y of opposite sign.",
    "state": {
      "labelTour": "all labels",
      "handedness": "Left-handed (Y flipped down)",
      "focalLength": 2.3
    }
  }
]

CAMERA VIEW (framing only). Call setCameraView({ projection, ...these }) AFTER all geometry is added. Keep the projection MECHANISM from PROJECTION TYPE above (orthographic / sheared-oblique / perspective). For perspective these params set the pose (azimuth/elevation/roll); for the two parallel projections pose is a standard default (see PROJECTION TYPE above), and these params set only roll and framing (heightFraction):
{
  "heightFraction": 0.62
}

NOTES: Build the box from six separate PlaneGeometry/Mesh faces rather than one BoxGeometry so each face gets its own colour and opacity and can be highlighted independently on click; render back faces with side: THREE.DoubleSide. Draw all visible box edges as solid LineSegments and the hidden edges as LineDashedMaterial (call computeLineDistances). Axes: thin CylinderGeometry shafts + ConeGeometry heads, all black, parented to a group so the handedness toggle can simply scale.y = -1 on the Y-axis group and relabel. Labels as CSS2DObject/sprite HTML so the serif typography and grey annotation colour match; leader arrows as QuadraticBezierCurve3 tubes in grey. Focal-length slider should move the z = -f face, rescale the side/top faces and re-lay the red dimension arrow in one update function. Keep the initial camera pose oblique (true side face facing the viewer, depth receding up-right) and only depart from it when the user orbits; add a 'reset view' affordance. Highlight on click = emissive boost + outline colour #FFB300 plus a small equation card showing the term that component controls.

Follow the interaction plan above.

