// @FIGURE_CODE_BEGIN
/* ---------------------------------------------------------------------------
   ELEMENT SPEC  (logical world frame:  +Z = optical axis = scene +x,
                                        +Y = up          = scene +y,
                                        +X = lateral     = scene -z)
   near side face  (X=-1)   -> PlaneGeometry(1,1) scaled (f,2)   #A7AD8C
   top face        (Y=+1)   -> PlaneGeometry rot.x=-90          #AEB7BB
   bottom face     (Y=-1)   -> PlaneGeometry rot.x=-90          #8B9178
   far side face   (X=+1)   -> PlaneGeometry                     #99A083
   rear face       (Z=0)    -> PlaneGeometry rot.y=+90          #46503C
   projection plane(Z=-f)   -> PlaneGeometry rot.y=+90, 45% op. #A7AD8C
   visible edges            -> LineSegments  solid              #3C4A44
   hidden / image-plane edges-> LineSegments LineDashedMaterial #3C4A44
   pinhole                  -> CircleGeometry(0.17) rot.y=90     black
   X / Y / Z axes           -> Cylinder shaft + Cone head        black
   focal-length indicator   -> Cylinder + 2 Cones                #FF0000
   leader arrows            -> QuadraticBezier Tube + Cone       #7E9195
   all text                 -> addLabel (serif HTML)
--------------------------------------------------------------------------- */

const COL = {
  near: 0xA7AD8C, top: 0xAEB7BB, rear: 0x46503C, bottom: 0x8B9178,
  far: 0x99A083, edge: 0x3C4A44, grey: 0x7E9195, red: 0xFF0000, hl: 0xFFB300
};
const SERIF = "'Times New Roman', Times, serif";

/* shear constant of the scaffold oblique camera (depthScale 0.9 @ 45deg) */
const DEPTH_SCALE = 0.9;
const KS = DEPTH_SCALE * Math.SQRT1_2;
/* place something so that it lands at (sx,sy) of the printed view */
function atScreen(sx, sy, z) { z = (z === undefined) ? 1.3 : z; return new THREE.Vector3(sx + KS * z, sy + KS * z, z); }

function mkLabel(html, pos, opts) {
  opts = opts || {};
  const e = addLabel(html, pos, opts);
  e.div.style.fontFamily = SERIF;
  if (opts.italic) e.div.style.fontStyle = 'italic';
  e.baseColor = opts.color || '#111';
  return e;
}

/* ============================ BOX ======================================== */
const boxGroup = new THREE.Group();
scene.add(boxGroup);

function faceMat(c, o) {
  return new THREE.MeshBasicMaterial({
    color: c, side: THREE.DoubleSide,
    transparent: o !== undefined, opacity: o === undefined ? 1 : o,
    depthWrite: o === undefined
