}
const mNear = faceMat(COL.near), mFar = faceMat(COL.far), mTop = faceMat(COL.top),
  mBottom = faceMat(COL.bottom), mRear = faceMat(COL.rear), mProj = faceMat(COL.proj, 0.45);

function mkFace(mat) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), mat);
  boxGroup.add(m);
  return m;
}
const nearFace = mkFace(mNear);
const farFace = mkFace(mFar);
const topFace = mkFace(mTop); topFace.rotation.x = -Math.PI / 2;
const bottomFace = mkFace(mBottom); bottomFace.rotation.x = -Math.PI / 2;
const rearFace = mkFace(mRear); rearFace.rotation.y = Math.PI / 2;
const projFace = mkFace(mProj); projFace.rotation.y = Math.PI / 2;
projFace.renderOrder = 3;

/* orange highlight outlines (local unit square -> follows face scale) */
function mkOutline(parent) {
  const pts = [new THREE.Vector3(-0.5, -0.5, 0), new THREE.Vector3(0.5, -0.5, 0),
  new THREE.Vector3(0.5, 0.5, 0), new THREE.Vector3(-0.5, 0.5, 0)];
  const l = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: COL.hl }));
  l.visible = false; l.renderOrder = 5;
  parent.add(l);
  return l;
}
const projOutline = mkOutline(projFace);
const nearOutline = mkOutline(nearFace);
const topOutline = mkOutline(topFace);
const rearOutline = mkOutline(rearFace);

/* ---- edges --------------------------------------------------------------- */
const solidEdges = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: COL.edge }));
const dashEdges = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineDashedMaterial({ color: COL.edge, dashSize: 0.14, gapSize: 0.09 }));
scene.add(solidEdges, dashEdges);

function rebuildEdges(f) {
  const S = [], D = [];
  const seg = (a, p, q) => { a.push(p[0], p[1], p[2], q[0], q[1], q[2]); };
  /* rear panel (z_logical = 0  ->  scene x = 0) */
  seg(S, [0, -1, 1], [0, 1, 1]);
  seg(S, [0, 1, 1], [0, 1, -1]);
  seg(S, [0, 1, -1], [0, -1, -1]);
  seg(S, [0, -1, -1], [0, -1, 1]);
  /* near side face top & bottom rails */
  seg(S, [-f, 1, 1], [0, 1, 1]);
  seg(S, [-f, -1, 1], [0, -1, 1]);
  /* top-far silhouette rail */
  seg(S, [-f, 1, -1], [0, 1, -1]);
  /* projection plane outline : all dashed */
  seg(D, [-f, -1, 1], [-f, 1, 1]);
  seg(D, [-f, 1, 1], [-f, 1, -1]);
  seg(D, [-f, 1, -1], [-f, -1, -1]);
  seg(D, [-f, -1, -1], [-f, -1, 1]);

  const gs = new THREE.BufferGeometry();
  gs.setAttribute('position', new THREE.Float32BufferAttribute(S, 3));
  solidEdges.geometry.dispose(); solidEdges.geometry = gs;

  const gd = new THREE.BufferGeometry();
  gd.setAttribute('position', new THREE.Float32BufferAttribute(D, 3));
  dashEdges.geometry.dispose(); dashEdges.geometry = gd;
  dashEdges.computeLineDistances();
}

/* ============================ PINHOLE ==================================== */
const pinhole = new THREE.Mesh(new THREE.CircleGeometry(0.17, 40),
  new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide }));
pinhole.rotation.y = Math.PI / 2;
pinhole.position.set(0.02, 0, 0);
pinhole.renderOrder = 4;
scene.add(pinhole);

const pinRing = new THREE.Mesh(new THREE.RingGeometry(0.23, 0.31, 40),
  new THREE.MeshBasicMaterial({ color: COL.hl, side: THREE.DoubleSide }));
pinRing.rotation.y = Math.PI / 2;
pinRing.position.set(0.03, 0, 0);
pinRing.visible = false;
scene.add(pinRing);

/* ============================ AXES ======================================= */
function makeAxis(len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide });
  const headH = 0.34, headR = 0.13, r = 0.035;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len - headH, 14), mat);
  shaft.position.y = (len - headH) / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headH, 22), mat);
  head.position.y = len - headH / 2;
  g.add(shaft, head);
  g.userData.mat = mat;
  return g;
}
const zAxis = makeAxis(4.5); zAxis.rotation.z = -Math.PI / 2;      // scene +x
const xAxis = makeAxis(2.6); xAxis.rotation.x = -Math.PI / 2;      // scene -z
const yAxis = makeAxis(3.4);                                       // scene +y
const yWrap = new THREE.Group(); yWrap.add(yAxis);
scene.add(zAxis, xAxis, yWrap);

/* ==================== FOCAL LENGTH INDICATOR ============================= */
const fMat = new THREE.MeshBasicMaterial({ color: COL.red, side: THREE.DoubleSide });
const fGroup = new THREE.Group();
const fShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 1, 12), fMat);
fShaft.rotation.z = Math.PI / 2;
const fHeadL = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.28, 16), fMat);
fHeadL.rotation.z = Math.PI / 2;
const fHeadR = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.28, 16), fMat);
fHeadR.rotation.z = -Math.PI / 2;
fGroup.add(fShaft, fHeadL, fHeadR);
fGroup.position.set(0, -1.35, 1);
scene.add(fGroup);

/* ==================== GREY LEADER ARROWS ================================= */
const greyMat = new THREE.MeshBasicMaterial({ color: COL.grey, side: THREE.DoubleSide });
function leader(p0, p1, p2) {
  const g = new THREE.Group();
  const curve = new THREE.QuadraticBezierCurve3(p0, p1, p2);
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 40, 0.028, 8, false), greyMat);
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.24, 14), greyMat);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  head.position.copy(p2).addScaledVector(tan, -0.12);
  g.add(tube, head);
  scene.add(g);
  return g;
}
const arrProj = leader(atScreen(-3.95, 1.15), atScreen(-3.85, 0.0), atScreen(-2.55, -0.45));
const arrOpt = leader(atScreen(3.35, 1.00), atScreen(3.15, 0.60), atScreen(2.90, 0.18));
const arrPin = leader(atScreen(1.40, -1.50), atScreen(0.85, -1.05), atScreen(0.32, -0.36));

/* ============================ BUILD ====================================== */
let fVal = 2.3;
function updateF(f) {
  fVal = f;
  nearFace.position.set(-f / 2, 0, 1); nearFace.scale.set(f, 2, 1);
  farFace.position.set(-f / 2, 0, -1); farFace.scale.set(f, 2, 1);
  topFace.position.set(-f / 2, 1, 0); topFace.scale.set(f, 2, 1);
  bottomFace.position.set(-f / 2, -1, 0); bottomFace.scale.set(f, 2, 1);
  rearFace.position.set(0, 0, 0); rearFace.scale.set(2, 2, 1);
  projFace.position.set(-f, 0, 0); projFace.scale.set(2, 2, 1);
  rebuildEdges(f);
  fShaft.scale.y = Math.max(0.05, f - 0.30);
  fShaft.position.x = -f / 2;
  fHeadL.position.x = -f + 0.14;
  fHeadR.position.x = -0.14;
  if (typeof lblF !== 'undefined') lblF.pos.set(-f / 2, -1.98, 1);
  updateCard();
}
updateF(fVal);

/* ============================ CAMERA ===================================== */
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 45,
  depthScale: DEPTH_SCALE,
  heightFraction: 0.62,
  target: [0.15, 0.7, 0]
});

/* ============================ LABELS ===================================== */
const lblTitle = mkLabel('Pinhole camera', new THREE.Vector3(-3.4, 3.2, 0), { fontSize: '19px' });
const lblWorld = mkLabel('World coordinates', new THREE.Vector3(2.0, 3.2, 0), { fontSize: '19px' });

const lblY = mkLabel('Y', new THREE.Vector3(0, 3.4, 0), { fontSize: '23px', offset: [-20, -8] });
const lblX = mkLabel('X', new THREE.Vector3(0, 0, -2.6), { fontSize: '23px', offset: [-24, -14] });
const lblZ = mkLabel('Z', new THREE.Vector3(4.5, 0, 0), { fontSize: '23px', offset: [-12, 28] });
const lblF = mkLabel('f', new THREE.Vector3(-fVal / 2, -1.98, 1), { fontSize: '22px', italic: true });

const lblProj = mkLabel('Projection plane', atScreen(-4.15, 1.62), { fontSize: '17px', color: '#7E9195' });
const lblOpt = mkLabel('Optical / principal axis', atScreen(3.55, 1.35), { fontSize: '17px', color: '#7E9195' });
const lblPin = mkLabel('Pinhole / camera center', atScreen(2.20, -1.85), { fontSize: '17px', color: '#7E9195' });

const ANNOS = {
  proj: { lbl: lblProj, arr: arrProj },
  optical: { lbl: lblOpt, arr: arrOpt },
  pinhole: { lbl: lblPin, arr: arrPin }
};
function showAnno(key, v) {
  ANNOS[key].lbl.div.style.visibility = v ? 'visible' : 'hidden';
  ANNOS[key].arr.visible = v;
}

/* ============================ HIGHLIGHT ================================== */
let currentPick = null;

function clearHighlight() {
