  else if (key === 'yaxis') { yAxis.userData.mat.color.set(COL.hl); lblY.div.style.color = '#C07A00'; }
  else if (key === 'xaxis') { xAxis.userData.mat.color.set(COL.hl); lblX.div.style.color = '#C07A00'; }
  else if (key === 'plane') { projOutline.visible = true; mProj.opacity = 0.75; }
  else if (key === 'pinhole') { pinRing.visible = true; }
  else if (key === 'farrow') { fMat.color.set(COL.hl); lblF.div.style.color = '#C07A00'; }
  else if (key === 'body') { nearOutline.visible = topOutline.visible = rearOutline.visible = true; }
