/* ============================ CLICK TARGETS ============================== */
registerInteractive(pinhole, {
  title: CARD.pinhole[0], body: CARD.pinhole[1], tooltip: 'Pinhole / camera centre',
  onClick: () => pick('pinhole')
});
registerInteractive(zAxis, {
  title: CARD.zaxis[0], body: CARD.zaxis[1], tooltip: 'Optical / principal axis',
  onClick: () => pick('zaxis')
});
registerInteractive(yAxis, {
  title: CARD.yaxis[0], body: CARD.yaxis[1], tooltip: 'Y axis',
  onClick: () => pick('yaxis')
});
registerInteractive(xAxis, {
  title: CARD.xaxis[0], body: CARD.xaxis[1], tooltip: 'X axis',
  onClick: () => pick('xaxis')
});
registerInteractive(projFace, {
  title: CARD.plane[0], body: CARD.plane[1], tooltip: 'Projection plane',
  onClick: () => pick('plane')
});
registerInteractive(fGroup, {
  title: CARD.farrow[0], body: CARD.farrow[1], tooltip: 'Focal length f',
  onClick: () => pick('farrow')
});
registerInteractive(boxGroup, {
  title: CARD.body[0], body: CARD.body[1], tooltip: 'Camera body',
  onClick: () => pick('body')
});

/* ============================ UI WIRING ================================== */
document.getElementById('btnReset').style.display = '';

const tourSel = document.getElementById('labelTour');
const handSel = document.getElementById('handedness');
const slider = document.getElementById('focalLength');
const readout = document.getElementById('fReadout');

const TOUR = {
  none: { annos: [], hl: null },
  z: { annos: ['optical'], hl: 'zaxis' },
  y: { annos: [], hl: 'yaxis' },
  x: { annos: [], hl: 'xaxis' },
  plane: { annos: ['proj'], hl: 'plane' },
  pinhole: { annos: ['pinhole'], hl: 'pinhole' },
  all: { annos: ['proj', 'optical', 'pinhole'], hl: null }
};

function applyTour() {
  const t = TOUR[tourSel.value] || TOUR.all;
  Object.keys(ANNOS).forEach(k => showAnno(k, t.annos.indexOf(k) >= 0));
  currentPick = t.hl;
  applyHighlight(t.hl);
  if (t.hl && CARD[t.hl]) { cardTitle.textContent = CARD[t.hl][0]; cardBody.textContent = CARD[t.hl][1]; }
  updateCard();
}
tourSel.addEventListener('change', applyTour);

function applyHand() {
  const left = handSel.value === '1';
  yWrap.scale.y = left ? -1 : 1;
  lblY.pos.set(0, left ? -3.4 : 3.4, 0);
  lblY.offset = left ? [-20, 10] : [-20, -8];
  updateCard();
}
handSel.addEventListener('change', applyHand);

slider.addEventListener('input', () => {
  fTween = null;
  const v = parseFloat(slider.value);
  readout.textContent = v.toFixed(2);
  updateF(v);
});

/* ------- f tween -------- */
let fTween = null;
function tweenF(target, ms) {
  if (Math.abs(target - fVal) < 1e-4) return;
  fTween = { s: fVal, t: target, t0: performance.now(), ms: ms || 700 };
}
function tickTween() {
  requestAnimationFrame(tickTween);
  if (!fTween) return;
  const u = Math.min(1, (performance.now() - fTween.t0) / fTween.ms);
  const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
  const v = fTween.s + (fTween.t - fTween.s) * e;
  slider.value = v.toFixed(2);
  readout.textContent = v.toFixed(2);
  updateF(v);
  if (u >= 1) fTween = null;
}
tickTween();

/* ------- guided tour -------- */
const STEPS = [
  {
    title: '1 · The camera body',
    text: 'A rectangular camera box sits along the negative Z direction. Its rear wall carries a tiny hole at the world origin; light entering there falls on the plane at the far end of the box.',
    tour: 'none', f: 2.3, hand: '0'
  },
  {
    title: '2 · Optical axis and camera centre',
    text: 'Z points out of the pinhole into the scene: this is the optical or principal axis, and the pinhole itself is the camera centre — the single point every ray passes through.',
    tour: 'z', f: 2.3, hand: '0'
  },
  {
    title: '3 · Completing the right-handed frame',
    text: 'Y points up and X points laterally, so X × Y = Z: the standard right-handed world frame anchored at the camera centre.',
    tour: 'x', f: 2.3, hand: '0'
  },
  {
    title: '4 · Projection plane and focal length',
    text: 'The image forms on the projection plane at the far end of the box, a distance f behind the pinhole. Drag f and watch the plane move: a longer f magnifies the image, since x = f·X/Z.',
    tour: 'plane', f: 3.4, hand: '0'
  },
  {
    title: '5 · Right- vs left-handed convention',
    text: 'Flipping Y to point down gives the left-handed convention used by many image-coordinate systems; the same 3D point now maps to an image y of opposite sign.',
    tour: 'all', f: 2.3, hand: '1'
  }
];
let stepIdx = -1;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  stepText.textContent = s.text;
  tourSel.value = s.tour; applyTour();
  handSel.value = s.hand; applyHand();
  tweenF(s.f, 700);
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx <= 0 ? 0 : stepIdx - 1));

/* initial state: the printed figure — every callout visible */
applyHand();
applyTour();
updateCard();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:bold;font-size:12px;margin-bottom:2px">Pinhole camera model</div>

<label>Name the parts
  <select id="labelTour">
    <option value="none">none</option>
    <option value="z">Z / optical axis</option>
    <option value="y">Y axis</option>
    <option value="x">X axis</option>
    <option value="plane">projection plane</option>
    <option value="pinhole">pinhole / camera centre</option>
    <option value="all" selected>all labels</option>
  </select>
</label>

<label>Coordinate convention
  <select id="handedness">
    <option value="0">Right-handed (X right, Y up, Z forward)</option>
    <option value="1">Left-handed (Y flipped down)</option>
  </select>
</label>

<label>Focal length f = <span id="fReadout">2.30</span>
  <input type="range" id="focalLength" min="0.6" max="4" step="0.1" value="2.3">
</label>

<div id="infoCard" style="border:1px solid #d7dbe0;border-radius:4px;padding:6px 8px;background:#fff;line-height:1.4">
  <div id="cardTitle" style="font-weight:bold">Click a component</div>
  <div id="cardBody">Click the pinhole, the Z axis, the projection plane, the red <i>f</i> arrow or the camera body to see the term it controls.</div>
  <div id="cardMath" style="margin-top:4px;font-family:ui-monospace,Consolas,monospace;font-size:11px;color:#333"></div>
</div>

<div style="margin-top:2px;font-weight:bold" id="stepTitle">Guided tour</div>
<div id="stepText" style="line-height:1.4">Step through the five stages of the construction, or drag the figure to leave the printed oblique view.</div>
<div style="display:flex;gap:4px">
  <button id="stepPrev">◀ Prev</button>
  <button id="stepNext">Next ▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------------------------------------------------------------------------
   ELEMENT SPEC   (scene axes:  scene +X = world Z = optical axis, screen right
                                scene +Y = world Y = up
                                scene -Z = world X = receding depth (up-right))
   near side face  (z=+1)  -> PlaneGeometry(1,1) scale(f,2)      #A7AD8C
   far side face   (z=-1)  -> PlaneGeometry(1,1) scale(f,2)      #99A083
   top face        (y=+1)  -> PlaneGeometry rot.x=-90            #AEB7BB
   bottom face     (y=-1)  -> PlaneGeometry rot.x=-90            #8B9178
   rear face       (x= 0)  -> PlaneGeometry rot.y=+90            #46503C
   projection plane(x=-f)  -> PlaneGeometry rot.y=+90, 45% op.   #A7AD8C
   visible edges (7)       -> CylinderGeometry bars r=0.022      #3C4A44
   proj-plane outline (4)  -> LineSegments  LineDashedMaterial (depthTest off)
   hidden bottom-far edge  -> LineSegments  LineDashedMaterial (occludable)
   pinhole                 -> CircleGeometry(0.19) rot.y=90      black (ellipse under shear)
   X / Y / Z axes          -> Cylinder shaft + Cone head         black
   focal-length indicator  -> Cylinder + 2 Cones                 #FF0000
   grey leader arrows (3)  -> QuadraticBezierCurve3 Tube + Cone  #7E9195
   all text                -> addLabel (serif HTML)
--------------------------------------------------------------------------- */

const COL = {
  near: 0xA7AD8C, far: 0x99A083, top: 0xAEB7BB, bottom: 0x8B9178,
  rear: 0x46503C, proj: 0xA7AD8C, edge: 0x3C4A44,
  grey: 0x7E9195, red: 0xFF0000, hl: 0xFFB300
};
const SERIF = "'Times New Roman', Times, serif";

/* oblique (cabinet/cavalier) constants — must match setCameraView below */
const OBQ = { angle: 48, depth: 1.0 };
const KX = Math.cos(THREE.MathUtils.degToRad(OBQ.angle)) * OBQ.depth;
const KY = Math.sin(THREE.MathUtils.degToRad(OBQ.angle)) * OBQ.depth;
/* a point placed on the z = 0 plane lands exactly at screen (sx, sy) */
function S(sx, sy) { return new THREE.Vector3(sx, sy, 0); }
function V(x, y, z) { return new THREE.Vector3(x, y, z); }

/* ---- DOM handles (grabbed up front: nothing below may hit a TDZ) -------- */
const tourSel = document.getElementById('labelTour');
const handSel = document.getElementById('handedness');
const slider = document.getElementById('focalLength');
const readout = document.getElementById('fReadout');
const cardTitle = document.getElementById('cardTitle');
const cardBody = document.getElementById('cardBody');
const cardMath = document.getElementById('cardMath');
const stepTitleEl = document.getElementById('stepTitle');
const stepTextEl = document.getElementById('stepText');

/* ---- forward label slots (assigned after the camera is set) ------------- */
let lblTitle = null, lblWorld = null, lblY = null, lblX = null, lblZ = null, lblF = null;
let lblProj = null, lblOpt = null, lblPin = null;
let ANNOS = null;
let fVal = 2.3;
let currentPick = null;
let fTween = null;

/* =============================== FACES =================================== */
const boxGroup = new THREE.Group();
scene.add(boxGroup);

function faceMat(c, op) {
  return new THREE.MeshBasicMaterial({
    color: c, side: THREE.DoubleSide,
    transparent: op !== undefined,
    opacity: op === undefined ? 1 : op,
    depthWrite: op === undefined
  });
}
const mNear = faceMat(COL.near), mFar = faceMat(COL.far), mTop = faceMat(COL.top),
  mBottom = faceMat(COL.bottom), mRear = faceMat(COL.rear), mProj = faceMat(COL.proj, 0.45);

function mkFace(mat) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), mat);
  boxGroup.add(m);
  return m;
}
const nearFace = mkFace(mNear);
const farFace = mkFace(mFar);
const topFace = mkFace(mTop); topFace.rotation.x = -Math.PI / 2;
const bottomFace = mkFace(mBottom); bottomFace.rotation.x = -Math.PI / 2;
const rearFace = mkFace(mRear); rearFace.rotation.y = Math.PI / 2;
const projFace = mkFace(mProj); projFace.rotation.y = Math.PI / 2;
projFace.renderOrder = 2;

/* orange highlight outlines (unit square in local space -> follows scale) */
function mkOutline(parent) {
  const pts = [V(-0.5, -0.5, 0), V(0.5, -0.5, 0), V(0.5, 0.5, 0), V(-0.5, 0.5, 0)];
  const l = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: COL.hl, depthTest: false }));
  l.visible = false; l.renderOrder = 7;
  parent.add(l);
  return l;
}
const projOutline = mkOutline(projFace);
const nearOutline = mkOutline(nearFace);
const topOutline = mkOutline(topFace);
const rearOutline = mkOutline(rearFace);

/* =============================== EDGES =================================== */
const edgeMat = new THREE.MeshBasicMaterial({ color: COL.edge });
const solidGroup = new THREE.Group();
scene.add(solidGroup);
const solidBars = [];
const _UP = V(0, 1, 0);
for (let i = 0; i < 7; i++) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 1, 8), edgeMat);
  solidGroup.add(m);
  solidBars.push(m);
}
function setBar(m, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.scale.set(1, len, 1);
  m.quaternion.setFromUnitVectors(_UP, dir.normalize());
}

/* projection-plane outline: dashed and drawn over everything (print convention) */
const dashMatFront = new THREE.LineDashedMaterial({
  color: COL.edge, dashSize: 0.17, gapSize: 0.11, depthTest: false
});
const dashPlane = new THREE.LineSegments(new THREE.BufferGeometry(), dashMatFront);
dashPlane.renderOrder = 6;
scene.add(dashPlane);

/* genuinely hidden bottom-far edge: dashed but occluded by the solid faces */
const dashMatBack = new THREE.LineDashedMaterial({ color: COL.edge, dashSize: 0.17, gapSize: 0.11 });
const dashHidden = new THREE.LineSegments(new THREE.BufferGeometry(), dashMatBack);
scene.add(dashHidden);

function rebuildDashed(f) {
  const P = [
    -f, -1, 1, -f, 1, 1,     // near vertical  (left edge of the true-shape face)
    -f, 1, 1, -f, 1, -1,     // upper diagonal receding up-right
    -f, 1, -1, -f, -1, -1,   // far vertical
    -f, -1, -1, -f, -1, 1    // bottom diagonal crossing the near face
  ];
  const g1 = new THREE.BufferGeometry();
  g1.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  dashPlane.geometry.dispose(); dashPlane.geometry = g1; dashPlane.computeLineDistances();

  const H = [-f, -1, -1, 0, -1, -1];
  const g2 = new THREE.BufferGeometry();
  g2.setAttribute('position', new THREE.Float32BufferAttribute(H, 3));
  dashHidden.geometry.dispose(); dashHidden.geometry = g2; dashHidden.computeLineDistances();
}

/* ============================== PINHOLE ================================== */
const pinhole = new THREE.Mesh(new THREE.CircleGeometry(0.19, 48),
  new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide }));
pinhole.rotation.y = Math.PI / 2;
pinhole.position.set(0.012, 0, 0);
pinhole.renderOrder = 4;
scene.add(pinhole);

const pinRing = new THREE.Mesh(new THREE.RingGeometry(0.27, 0.36, 48),
  new THREE.MeshBasicMaterial({ color: COL.hl, side: THREE.DoubleSide, depthTest: false }));
pinRing.rotation.y = Math.PI / 2;
pinRing.position.set(0.02, 0, 0);
pinRing.renderOrder = 8;
pinRing.visible = false;
scene.add(pinRing);

/* =============================== AXES ==================================== */
function makeAxis(len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
  const headH = 0.36, headR = 0.135, r = 0.032;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len - headH, 14), mat);
  shaft.position.y = (len - headH) / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headH, 24), mat);
  head.position.y = len - headH / 2;
  g.add(shaft, head);
  g.userData.mat = mat;
  return g;
}
const Z_LEN = 4.2, X_LEN = 2.6, Y_LEN = 3.55;
const zAxis = makeAxis(Z_LEN); zAxis.rotation.z = -Math.PI / 2;   // -> scene +X (screen right)
const xAxis = makeAxis(X_LEN); xAxis.rotation.x = -Math.PI / 2;   // -> scene -Z (recedes up-right)
const yAxis = makeAxis(Y_LEN);                                    // -> scene +Y
const yWrap = new THREE.Group(); yWrap.add(yAxis);
scene.add(zAxis, xAxis, yWrap);

/* ====================== FOCAL-LENGTH INDICATOR =========================== */
const fMat = new THREE.MeshBasicMaterial({ color: COL.red });
const fGroup = new THREE.Group();
const fShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 1, 12), fMat);
fShaft.rotation.z = Math.PI / 2;
const fHeadL = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.3, 18), fMat);
fHeadL.rotation.z = Math.PI / 2;                                  // points -X
const fHeadR = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.3, 18), fMat);
fHeadR.rotation.z = -Math.PI / 2;                                 // points +X
fGroup.add(fShaft, fHeadL, fHeadR);
fGroup.position.set(0, -1.4, 1);                                  // on the near-face plane
scene.add(fGroup);

/* ========================= GREY LEADER ARROWS ============================ */
const greyMat = new THREE.MeshBasicMaterial({ color: COL.grey, depthTest: false });
function leader(p0, p1, p2) {
  const g = new THREE.Group();
  const curve = new THREE.QuadraticBezierCurve3(p0, p1, p2);
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 48, 0.028, 8, false), greyMat);
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.095, 0.26, 16), greyMat);
  head.quaternion.setFromUnitVectors(_UP, tan);
  head.position.copy(p2).addScaledVector(tan, -0.13);
  g.add(tube, head);
  g.renderOrder = 5;
  tube.renderOrder = 5; head.renderOrder = 5;
  scene.add(g);
  return g;
}
const arrProj = leader(S(-3.70, 0.62), S(-3.32, -0.62), S(-2.30, -0.36));
const arrOpt = leader(S(3.28, 0.52), S(3.02, 0.34), S(2.72, 0.10));
const arrPin = leader(S(1.02, -0.86), S(0.62, -0.56), S(0.30, -0.20));

/* ========================== EQUATION CARD ================================ */
const CARD = {
  pinhole: ['Pinhole / camera centre C',
    'Every ray from the scene passes through this single point. It is the origin of the world frame, so scene points are measured as (X, Y, Z) from here.'],
  zaxis: ['Optical / principal axis (Z)',
    'Z is the depth of a scene point — the denominator of the projection. Doubling Z halves the image point.'],
  yaxis: ['Y axis',
    'Y is the vertical scene coordinate — the numerator of y = f·Y/Z.'],
  xaxis: ['X axis',
    'X is the lateral scene coordinate (the receding direction here) — the numerator of x = f·X/Z.'],
  plane: ['Projection / image plane',
    'The far wall of the box, a distance f behind the pinhole. The image of (X, Y, Z) forms here.'],
  farrow: ['Focal length f',
    'Distance from the pinhole to the projection plane. It acts as a pure magnification factor.'],
  body: ['Camera body',
    'A light-tight box: the pinhole sits in the rear wall at the origin, the image plane closes the far end, a distance f away.']
};

function updateCard() {
  if (!cardMath) return;
  const sy = (handSel && handSel.value === '1') ? -1 : 1;
  const X = 1, Y = 1, Z = 4;
  const ix = fVal * X / Z, iy = sy * fVal * Y / Z;
  if (currentPick && CARD[currentPick]) {
    cardTitle.textContent = CARD[currentPick][0];
    cardBody.textContent = CARD[currentPick][1];
  }
  cardMath.innerHTML =
    'x = f·X/Z , y = ' + (sy < 0 ? '−' : '') + 'f·Y/Z<br>' +
    'f = ' + fVal.toFixed(2) + ' : (1, 1, 4) → (' + ix.toFixed(2) + ', ' + iy.toFixed(2) + ')';
}

/* ============================ BUILD / UPDATE ============================= */
function updateF(f) {
  fVal = f;
  nearFace.position.set(-f / 2, 0, 1); nearFace.scale.set(f, 2, 1);
  farFace.position.set(-f / 2, 0, -1); farFace.scale.set(f, 2, 1);
  topFace.position.set(-f / 2, 1, 0); topFace.scale.set(f, 2, 1);
  bottomFace.position.set(-f / 2, -1, 0); bottomFace.scale.set(f, 2, 1);
  rearFace.position.set(0, 0, 0); rearFace.scale.set(2, 2, 1);
  projFace.position.set(-f, 0, 0); projFace.scale.set(2, 2, 1);

  /* 7 solid (visible) edges */
  setBar(solidBars[0], V(0, -1, 1), V(0, -1, -1));   // rear bottom
  setBar(solidBars[1], V(0, 1, 1), V(0, 1, -1));   // rear top
  setBar(solidBars[2], V(0, -1, 1), V(0, 1, 1));   // rear/near vertical
  setBar(solidBars[3], V(0, -1, -1), V(0, 1, -1));   // rear/far vertical
  setBar(solidBars[4], V(-f, 1, 1), V(0, 1, 1));   // top-near rail
  setBar(solidBars[5], V(-f, 1, -1), V(0, 1, -1));   // top-far silhouette
  setBar(solidBars[6], V(-f, -1, 1), V(0, -1, 1));   // near-bottom rail

  rebuildDashed(f);

  fShaft.scale.y = Math.max(0.05, f - 0.34);
  fShaft.position.x = -f / 2;
  fHeadL.position.x = -f + 0.15;
  fHeadR.position.x = -0.15;

  if (lblF) lblF.pos.set(-f / 2, -1.95, 1);
  updateCard();
}
updateF(fVal);

/* ============================== CAMERA =================================== */
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: OBQ.angle,
  depthScale: OBQ.depth,
  heightFraction: 0.62
});
document.getElementById('btnReset').style.display = '';

/* =============================== LABELS ================================== */
function mkLabel(html, pos, opts) {
  opts = opts || {};
  const e = addLabel(html, pos, opts);
  e.div.style.fontFamily = SERIF;
  if (opts.italic) e.div.style.fontStyle = 'italic';
  e.baseColor = opts.color || '#111';
  return e;
}

lblTitle = mkLabel('Pinhole camera', S(-3.45, 3.15), { fontSize: '24px' });
lblWorld = mkLabel('World coordinates', S(2.85, 3.15), { fontSize: '24px' });

lblY = mkLabel('Y', V(0, Y_LEN, 0), { fontSize: '28px', offset: [-24, -2] });
lblX = mkLabel('X', V(0, 0, -X_LEN), { fontSize: '28px', offset: [-26, -18] });
lblZ = mkLabel('Z', V(Z_LEN, 0, 0), { fontSize: '28px', offset: [12, 30] });
lblF = mkLabel('f', V(-fVal / 2, -1.95, 1), { fontSize: '26px', italic: true });

lblProj = mkLabel('Projection plane', S(-3.95, 0.98), { fontSize: '19px', color: '#6B7E82' });
lblOpt = mkLabel('Optical / principal axis', S(3.72, 0.80), { fontSize: '19px', color: '#6B7E82' });
lblPin = mkLabel('Pinhole / camera center', S(2.38, -1.02), { fontSize: '19px', color: '#6B7E82' });

ANNOS = {
  proj: { lbl: lblProj, arr: arrProj },
  optical: { lbl: lblOpt, arr: arrOpt },
  pinhole: { lbl: lblPin, arr: arrPin }
};
function showAnno(key, v) {
  ANNOS[key].lbl.div.style.visibility = v ? 'visible' : 'hidden';
  ANNOS[key].arr.visible = v;
}

/* ============================= HIGHLIGHT ================================= */
function clearHighlight() {
  zAxis.userData.mat.color.set(0x000000);
  yAxis.userData.mat.color.set(0x000000);
  xAxis.userData.mat.color.set(0x000000);
  fMat.color.set(COL.red);
  projOutline.visible = nearOutline.visible = topOutline.visible = rearOutline.visible = false;
  pinRing.visible = false;
  mProj.opacity = 0.45;
  [lblX, lblY, lblZ, lblF].forEach(l => { if (l) l.div.style.color = l.baseColor; });
}

function applyHighlight(key) {
