function makeAxis(len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
  const headH = 0.34, headR = 0.13, r = 0.028;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len - headH, 14), mat);
  shaft.position.y = (len - headH) / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headH, 24), mat);
  head.position.y = len - headH / 2;
  g.add(shaft, head);
  g.userData.mat = mat;
  return g;
}
