  /* 7 solid (visible) edges */
  setBar(solidBars[0], V(0, -1, 1), V(0, -1, -1));   // rear-bottom diagonal
  setBar(solidBars[1], V(0, 1, 1), V(0, 1, -1));   // rear-top diagonal
